from __future__ import annotations

import datetime as dt
import email.utils
import re
from typing import Any, Callable, Iterable

# ---- from search_case_media.py
def compact_spaces(value: str) -> str:
    return re.sub(r"\s+", " ", value or "").strip()

def dedupe_keep_order(values: Iterable[str]) -> list[str]:
    seen: set[str] = set()
    out: list[str] = []
    for value in values:
        cleaned = compact_spaces(value)
        if cleaned and cleaned not in seen:
            seen.add(cleaned)
            out.append(cleaned)
    return out

def quote_phrase(value: str) -> str:
    escaped = value.strip().replace('"', r"\"")
    return f'"{escaped}"'

def infer_case_party_names(case_name: str) -> list[str]:
    cleaned = compact_spaces(re.sub(r"\([^)]*\)", "", case_name or ""))
    if not cleaned:
        return []
    parts = [
        compact_spaces(part.strip(" ,:;"))
        for part in re.split(r"\s+(?:נ\.|נ'|נ׳|נגד)\s+", cleaned)
        if compact_spaces(part.strip(" ,:;"))
    ]
    if len(parts) < 2:
        return []
    preferred = [part for part in parts if not _scm_is_institutional_party_name(part)]
    return dedupe_keep_order(preferred or parts)

def google_news_date_operators(start: dt.date, end: dt.date) -> tuple[str, str]:
    """Return after/before dates; before is exclusive, so add one day."""
    return start.isoformat(), (end + dt.timedelta(days=1)).isoformat()

def parse_rfc822_date(value: str) -> str:
    parsed = email.utils.parsedate_to_datetime(value)
    if parsed.tzinfo:
        parsed = parsed.astimezone(dt.timezone.utc)
    return parsed.date().isoformat()

def _scm_is_institutional_party_name(value: str) -> bool:
    cleaned = compact_spaces(value).casefold()
    institutional_terms = [
        "מדינת ישראל",
        "היועץ המשפטי",
        "התובע הצבאי",
        "לשכת עורכי הדין",
        "משטרת ישראל",
        "פרקליטות",
    ]
    return any(term in cleaned for term in institutional_terms)


